package com.travelbird.ai.repository;
import com.travelbird.place.entity.Place;import com.travelbird.trip.entity.TripWishlistPlace;import jakarta.persistence.EntityManager;import java.util.*;import org.springframework.stereotype.Repository;
@Repository public class AiRecommendationDataReader{private final EntityManager em;public AiRecommendationDataReader(EntityManager em){this.em=em;}public List<Place> places(Collection<Long> ids){if(ids.isEmpty())return List.of();return em.createQuery("select p from Place p join fetch p.region where p.id in :ids",Place.class).setParameter("ids",ids).getResultList();}public List<TripWishlistPlace> wishlist(Long tripId){return em.createQuery("select w from TripWishlistPlace w join fetch w.place p join fetch p.region where w.trip.id=:id order by p.id",TripWishlistPlace.class).setParameter("id",tripId).getResultList();}}
